#include "html.h"
/* Textbrowser: Darstellung und Bedienung. Das Parsen steckt in html.c, das Laden in http.c */
#define HMAX (4*1024*1024)
#define NH 24
#define UL 1200
#define VL 128
#define MAXF 256
typedef struct tabs_s tabs_t;
typedef struct { tabs_t*T; int inext,ifail,internal,fline,fhits,fidx; u32 ibytes; char find[64]; hpage g; char*html; int hlen,lat,plain,top,sel,wid,state; char url[UL]; char msg[80]; char (*hist)[UL]; int htop[NH],nh; char (*val)[VL]; u8 *edit; int num; } web_t;
enum { ST_NEW,ST_SAFE,ST_PLAIN,ST_ERR };
#define MAXT 6
#define MAXIM 24
#define IMAX (3*1024*1024)
#define IOUT 800000
#define DLMAX (32*1024*1024)
struct tabs_s { void*t[MAXT]; int n,cur; };
#define BDIR "/system/browser"
#define BMF BDIR "/bookmarks"
#define HIF BDIR "/history"
#define LMAX 16000
#define NOF BDIR "/noimages"
static web_t*cur; static win_t*curw;
static const char START_EN[]="<title>Violyx Internet</title><h1>Violyx Internet</h1><p>Welcome to the browser.</p><h2>Keys</h2><ul><li>Arrows and Page Up/Down scroll</li><li>Tab jumps to the next link, Shift+Tab back</li><li>Enter opens the link</li><li>Backspace goes back one page</li><li>Ctrl+L opens the address bar</li><li>N shows link numbers, number and Enter opens directly</li><li>Enter in search fields opens the input</li><li>Ctrl+R reloads, Ctrl+S saves the page</li><li>Ctrl+F searches the page, Ctrl+G jumps to the next hit</li><li>Ctrl+D adds a bookmark, Ctrl+B shows bookmarks, Ctrl+H history</li><li>Ctrl+I turns images off or on for this site</li><li>Ctrl+T opens a tab, Ctrl+Enter opens a link in a new tab, Ctrl+Page Up/Down switches tabs</li><li>Esc closes the tab or window</li></ul><h2>Try it</h2><ul><li><a href=\"https://en.wikipedia.org/\">Wikipedia</a></li><li><a href=\"https://lite.duckduckgo.com/lite/\">DuckDuckGo search</a></li><li><a href=\"https://de.wikipedia.org/\">Wikipedia (German)</a></li><li><a href=\"https://text.npr.org/\">NPR Text</a></li><li><a href=\"https://lite.cnn.com/\">CNN Lite</a></li><li><a href=\"https://lobste.rs/\">Lobsters</a></li><li><a href=\"https://example.com/\">example.com</a></li></ul><p>Please do not enter passwords here. Violyx is a hobby system without memory protection.</p>";
static const char START[]="<title>Violyx Internet</title><h1>Violyx Internet</h1><p>Willkommen im Browser.</p><h2>Tasten</h2><ul><li>Pfeile und Bild auf/ab scrollen</li><li>Tab springt zum nächsten Link, Umschalt+Tab zurück</li><li>Enter öffnet den Link</li><li>Rücktaste geht eine Seite zurück</li><li>Strg+L öffnet die Adresszeile</li><li>N zeigt Link-Nummern, Zahl und Enter öffnet direkt</li><li>Enter in Suchfeldern öffnet die Eingabe</li><li>Strg+R lädt neu, Strg+S speichert die Seite</li><li>Strg+F sucht auf der Seite, Strg+G springt zum nächsten Treffer</li><li>Strg+D merkt die Seite, Strg+B zeigt Lesezeichen, Strg+H den Verlauf</li><li>Strg+I schaltet Bilder für diese Website aus oder ein</li><li>Strg+T öffnet einen Tab, Strg+Enter einen Link im neuen Tab, Strg+Bild auf/ab wechselt den Tab</li><li>Esc schließt den Tab oder das Fenster</li></ul><h2>Zum Ausprobieren</h2><ul><li><a href=\"https://de.wikipedia.org/\">Wikipedia</a></li><li><a href=\"https://lite.duckduckgo.com/lite/\">DuckDuckGo Suche</a></li><li><a href=\"https://en.wikipedia.org/\">Wikipedia (Englisch)</a></li><li><a href=\"https://text.npr.org/\">NPR Text</a></li><li><a href=\"https://lite.cnn.com/\">CNN Lite</a></li><li><a href=\"https://lobste.rs/\">Lobsters</a></li><li><a href=\"https://example.com/\">example.com</a></li></ul><p>Bitte gib hier keine Passwörter ein. Violyx ist ein Hobbysystem ohne Speicherschutz.</p>";
static void layout(web_t*b,int w){ b->wid=w; html_lang=cfg_lang; html_layout(b->html,b->hlen,w,b->lat,b->plain,&b->g); }
static void relay(web_t*b,int w){ u32 off=b->top<b->g.nl?b->g.l[b->top].off:0; int oldnl=b->g.nl; layout(b,w); if(oldnl){ b->top=(int)((u64)b->top*b->g.nl/oldnl); } (void)off; if(b->top>=b->g.nl)b->top=b->g.nl?b->g.nl-1:0; b->sel=-1; }
static void prog(const char*t){ strlcpy_(cur->msg,t,80); ui_render(); ui_show(); }
static void img_reset(web_t*b){ hpage*g=&b->g; for(int i=0;i<g->maxim;i++)kfree(g->im[i].px); memset(g->im,0,sizeof(himg)*g->maxim); g->nim=0; b->inext=0; b->ifail=0; b->ibytes=0; }
static void setpage(web_t*b,const char*src,int n,int w){ img_reset(b); b->internal=0; b->find[0]=0; memcpy(b->html,src,n); b->html[n]=0; b->hlen=n; b->lat=0;b->plain=0;b->top=0;b->sel=-1; layout(b,w); }
static void errpage(web_t*b,const char*t,const char*d,int w){ static char e[512]; int n=ksnprintf(e,512,"<title>%s</title><h1>%s</h1><p>%s</p>",t,t,d); if(n>511)n=511; setpage(b,e,n,w); }
static const char*frag(const char*u){ const char*h=strchr(u,'#'); return h?h+1:0; }
static void jump(web_t*b,const char*f,int view){ if(!f||!*f)return; u32 h=html_hash(f); for(int i=0;i<b->g.nan;i++) if(b->g.anch[i].h==h){ b->top=b->g.anch[i].line; if(b->top>=b->g.nl)b->top=b->g.nl?b->g.nl-1:0; return; } }
static int has(const char*s,const char*n){ size_t l=strlen(n); for(;*s;s++){ size_t i=0; for(;i<l;i++){ char c=s[i]; if(c>='A'&&c<='Z')c+=32; if(c!=n[i])break; } if(i==l)return 1; } return 0; }
static void*memchr(const void*p,int c,size_t n){ const u8*q=p; for(size_t i=0;i<n;i++) if(q[i]==(u8)c)return (void*)(q+i); return 0; }
/* ---------- Lesezeichen und Verlauf: Zeilen "Adresse TAB Titel" ---------- */
static char bmk[LMAX],hsl[LMAX],noi[LMAX]; static int bml,hsn,non,lloaded;
static int rdf(const char*p,char*o){ if(!fs_ok())return 0; vfs_ent e; if(fsx_stat(p,&e)||e.dir||e.size>=LMAX)return 0; long n=fsx_read(p,o,e.size); return n<0?0:(int)n; }
static void lload(void){ if(lloaded)return; lloaded=1; bml=rdf(BMF,bmk); hsn=rdf(HIF,hsl); non=rdf(NOF,noi); }
static void lsave(const char*p,const char*b,int n){ if(!fs_ok())return; fsx_mkdir(BDIR,fs_now()); fsx_write(p,b,n,fs_now()); }
/* Entfernt eine Zeile mit dieser Adresse, liefert 1 wenn es sie gab */
static int ldel(char*b,int*n,const char*url){ size_t l=strlen(url); for(int i=0;i<*n;){ char*e=memchr(b+i,'\n',*n-i); int L=e?(int)(e-(b+i))+1:*n-i; if(L>(int)l&&b[i+l]=='\t'&&!memcmp(b+i,url,l)){ memmove(b+i,b+i+L,*n-i-L); *n-=L; return 1; } i+=L; } return 0; }
static void ladd(char*b,int*n,const char*url,const char*title){ int ul=strlen(url),tl=strlen(title); if(ul>400)return; if(*n+ul+tl+2>LMAX){ int cut=*n/3; char*e=memchr(b+cut,'\n',*n-cut); if(!e){ *n=0; } else { int c=(int)(e-b)+1; memmove(b,b+c,*n-c); *n-=c; } } memcpy(b+*n,url,ul); *n+=ul; b[(*n)++]='\t'; for(int i=0;i<tl;i++)b[(*n)++]=title[i]=='\n'||title[i]=='\t'?' ':title[i]; b[(*n)++]='\n'; }
/* Host der Adresse, Bilder sind je Website abschaltbar */
static void hostof(const char*u,char*o,int n){ const char*p=strstr(u,"://"); p=p?p+3:u; int l=0; while(*p&&*p!='/'&&*p!='?'&&*p!='#'&&l<n-1)o[l++]=*p++; o[l]=0; }
static int noimg_host(const char*u){ char h[120]; hostof(u,h,120); int l=strlen(h); if(!l)return 0; for(int i=0;i<non;){ char*e=memchr(noi+i,'\n',non-i); int L=e?(int)(e-(noi+i)):non-i; if(L>l&&noi[i+l]=='\t'&&!memcmp(noi+i,h,l))return 1; i+=L+1; } return 0; }
static int esc_(char*o,int p,int max,const char*s,int n,int cp){ for(int i=0;i<n&&p<max-10;i++){ u8 c=s[i]; if(c=='<'||c=='>'||c=='&'||c=='"'||(cp&&c>=0x80))p+=ksnprintf(o+p,max-p,"&#%d;",cp&&c>=0x80?html_cp437_uni(c):c); else o[p++]=c; } return p; }
static int lpage(char*o,int p,int max,const char*b,int n,int del){ int idx=0,cnt=0; for(int i=0;i<n;i++)cnt+=b[i]=='\n'; for(int i=n;i>0;){ int j=i-1; while(j>0&&b[j-1]!='\n')j--; const char*t=memchr(b+j,'\t',i-j); if(t&&p<max-2000){ int ul=(int)(t-(b+j)),tl=i-1-(int)(t-b)-1; p+=ksnprintf(o+p,max-p,"<li><a href=\""); p=esc_(o,p,max,b+j,ul,0); p+=ksnprintf(o+p,max-p,"\">"); if(tl>0)p=esc_(o,p,max,t+1,tl,1); else p=esc_(o,p,max,b+j,ul,0); p+=ksnprintf(o+p,max-p,"</a>"); if(del)p+=ksnprintf(o+p,max-p," <a href=\"violyx:bm-del?%d\">[x]</a>",cnt-1-idx); p+=ksnprintf(o+p,max-p,"</li>"); } idx++; i=j; } return p; }
static void showpage(win_t*w,web_t*b,const char*url,int n){ int wd=cw(w); img_reset(b); b->find[0]=0; b->hlen=n; b->html[n]=0; b->lat=0;b->plain=0;b->top=0;b->sel=-1; b->state=ST_NEW; b->internal=1; b->num=0; strlcpy_(b->url,url,UL); memset(b->edit,0,MAXF); layout(b,wd); }
static void pushh(web_t*b){ if(!b->url[0])return; if(b->nh==NH){ memmove(b->hist[0],b->hist[1],(NH-1)*UL); memmove(b->htop,b->htop+1,(NH-1)*sizeof(int)); b->nh--; } strlcpy_(b->hist[b->nh],b->url,UL); b->htop[b->nh]=b->top; b->nh++; }
static void internal(win_t*w,web_t*b,const char*u,int push){ lload(); char*o=b->html; int p=0,max=HMAX; const char*c=u+7; b->msg[0]=0; if(!strncmp(c,"bm-del?",7)){ int k=atoi(c+7),i=0,cnt=0; while(i<bml&&cnt<k){ char*e=memchr(bmk+i,'\n',bml-i); if(!e)break; i=(int)(e-bmk)+1; cnt++; } if(i<bml){ char*e=memchr(bmk+i,'\n',bml-i); int L=e?(int)(e-(bmk+i))+1:bml-i; memmove(bmk+i,bmk+i+L,bml-i-L); bml-=L; lsave(BMF,bmk,bml); } c="bookmarks"; push=0; }
  if(!strcmp(c,"hist-clear")){ if(dlg_confirm(TR("Verlauf","History"),TR("Gesamten Verlauf löschen?","Delete the whole history?"))){ hsn=0; lsave(HIF,hsl,0); } c="history"; push=0; } if(!strcmp(c,"cookies-clear")){ if(dlg_confirm("Cookies",TR("Alle Cookies löschen? Du wirst dann überall abgemeldet.","Delete all cookies? This signs you out everywhere."))){ cookie_clear(); } c="history"; push=0; }
  if(push)pushh(b); if(!strcmp(c,"bookmarks")){ p+=ksnprintf(o+p,max-p,"<title>%s</title><h1>%s</h1>",TR("Lesezeichen","Bookmarks"),TR("Lesezeichen","Bookmarks")); if(!bml)p+=ksnprintf(o+p,max-p,"<p>%s</p>",TR("Noch keine Lesezeichen. Strg+D merkt die aktuelle Seite.","No bookmarks yet. Ctrl+D adds the current page.")); else { p+=ksnprintf(o+p,max-p,"<ul>"); p=lpage(o,p,max,bmk,bml,1); p+=ksnprintf(o+p,max-p,"</ul><p>%s</p>",TR("[x] entfernt ein Lesezeichen.","[x] removes a bookmark.")); } showpage(w,b,"violyx:bookmarks",p); return; }
  if(!strcmp(c,"history")){ p+=ksnprintf(o+p,max-p,"<title>%s</title><h1>%s</h1><p><a href=\"violyx:hist-clear\">%s</a> &nbsp; <a href=\"violyx:cookies-clear\">%s (%d)</a></p>",TR("Verlauf","History"),TR("Verlauf","History"),TR("Verlauf löschen","Clear history"),TR("Cookies löschen","Clear cookies"),cookie_count()); if(hsn){ p+=ksnprintf(o+p,max-p,"<ul>"); p=lpage(o,p,max,hsl,hsn,0); p+=ksnprintf(o+p,max-p,"</ul>"); } showpage(w,b,"violyx:history",p); return; }
  p+=ksnprintf(o,max,"<title>Violyx</title><h1>%s</h1>",TR("Unbekannte Violyx-Seite","Unknown Violyx page")); showpage(w,b,u,p); }
/* Name fuer eine Datei aus der Adresse: nur harmlose Zeichen */
static void dlname(const char*url,const http_res*r,char*o,int n){ const char*t=url; for(const char*q=url;*q&&*q!='?'&&*q!='#';q++) if(*q=='/'&&q[1]&&q[1]!='?')t=q+1; int l=0; if(r->fname[0])strlcpy_(o,r->fname,n); else { for(;*t&&*t!='?'&&*t!='#'&&*t!='/'&&l<n-1&&l<56;t++){ char c=*t; o[l++]=(c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='.'||c=='-'||c=='_'?c:'_'; } o[l]=0; } if(!o[0]||o[0]=='.')strlcpy_(o,"download.bin",n); }
static void download(web_t*b,const char*url,char*data,int n,http_res*r){ char p[VFS_PATH],q[VFS_PATH],nm[64],m[100]; dlname(url,r,nm,64); ksnprintf(p,VFS_PATH,"%s/%s",fs_ok()?"/downloads":fsx_home(),nm); int kb=(n+1023)/1024; ksnprintf(m,100,TR("%s, %d KB. Speichern unter:","%s, %d KB. Save as:"),r->type[0]?r->type:"?",kb); b->msg[0]=0; if(!dlg_input(TR("Datei herunterladen","Download file"),m,p,VFS_PATH-1)){ strlcpy_(b->msg,TR("Download abgebrochen","Download cancelled"),80); return; } if(vfs_norm("/downloads",p,q,VFS_PATH)){ strlcpy_(b->msg,vfs_errstr(VE_INVAL,cfg_lang),80); return; } vfs_ent e; if(!fsx_stat(q,&e)){ if(e.dir||!dlg_confirm(TR("Datei herunterladen","Download file"),TR("Datei gibt es schon. Ersetzen?","File already exists. Replace it?"))){ strlcpy_(b->msg,TR("Download abgebrochen","Download cancelled"),80); return; } } int s=fsx_write(q,data,n,fs_now()); if(s){ strlcpy_(b->msg,vfs_errstr(s,cfg_lang),80); return; } ksnprintf(b->msg,80,TR("Gespeichert: %s","Saved: %s"),q); size_t L=strlen(q); if(L>4&&!strcmp(q+L-4,".vpk")){ int i=prog_install(q); if(i==0)strlcpy_(b->msg,TR("Programm installiert. Es steht jetzt unter F2.","Program installed. It is now listed under F2."),80); else if(i!=VE_DENIED)strlcpy_(b->msg,vfs_errstr(i,cfg_lang),80); } }
static void load(win_t*w,web_t*b,const char*url,int push,int top,const char*post){ static char u[UL]; strlcpy_(u,url,UL); if(!strncmp(u,"violyx:",7)){ internal(w,b,u,push); return; } cur=b;curw=w; static http_res r; int wd=cw(w); char*nb=kmalloc(HMAX+1); if(!nb){ strlcpy_(b->msg,TR("Nicht genug Arbeitsspeicher","Not enough memory"),80); return; }
  int n=http_fetch(u,post,nb,HMAX,&r,prog,0); b->msg[0]=0;
  if(n>=0){ int text=has(r.type,"text/plain"),html=has(r.type,"html")||!r.type[0],pic=has(r.type,"image/"); if(!text&&!html&&!pic){ if(r.truncated){ char*big=kmalloc(DLMAX+1); static http_res r2; if(!big)strlcpy_(b->msg,TR("Datei zu groß","File too large"),80); else { int m=http_fetch(u,post,big,DLMAX,&r2,prog,0); if(m<0)strlcpy_(b->msg,r2.err,80); else if(r2.truncated)strlcpy_(b->msg,TR("Datei zu groß oder unvollständig (Grenze 32 MB)","File too large or incomplete (limit 32 MB)"),80); else download(b,u,big,m,&r2); kfree(big); } } else download(b,u,nb,n,&r); kfree(nb); return; } }
  if(push)pushh(b); kfree(b->html); b->html=nb; memset(b->edit,0,MAXF); b->num=0; b->internal=0; img_reset(b); b->find[0]=0; strlcpy_(b->url,r.final_url[0]?r.final_url:u,UL); if(frag(u)&&!frag(b->url)){ size_t l=strlen(b->url); if(l+strlen(frag(u))+2<UL){ b->url[l]='#'; strlcpy_(b->url+l+1,frag(u),UL-l-1); } }
  if(n<0){ b->state=ST_ERR; if(r.cert_bad)errpage(b,TR("Verbindung abgelehnt","Connection refused"),r.err,wd); else errpage(b,TR("Seite nicht geladen","Page not loaded"),r.err,wd); return; }
  b->state=r.tls?ST_SAFE:ST_PLAIN; int text=has(r.type,"text/plain"); if(has(r.type,"image/")){ char*q=b->html; int p=ksnprintf(q,HMAX,"<title>%s</title><img src=\"",TR("Bild","Image")); p=esc_(q,p,HMAX,b->url,strlen(b->url),0); p+=ksnprintf(q+p,HMAX-p,"\" alt=\"%s\">",TR("Bild","Image")); n=p; text=0; r.type[0]=0; }
  b->hlen=n; b->plain=text; b->lat=has(r.type,"8859")||has(r.type,"1252")||has(r.type,"latin"); if(!r.type[0]||!has(r.type,"charset")){ char sv=n>1024?b->html[1024]:0; if(n>1024)b->html[1024]=0; if(has(b->html,"charset=iso-8859")||has(b->html,"charset=\"iso-8859")||has(b->html,"windows-1252"))b->lat=1; if(n>1024)b->html[1024]=sv; }
  lload(); b->g.noimg=noimg_host(b->url); b->top=0;b->sel=-1; layout(b,wd); if(top)b->top=top<b->g.nl?top:0; else jump(b,frag(u),0); if(r.truncated)strlcpy_(b->msg,TR("Seite gekürzt: Größenlimit oder Verbindung abgebrochen","Page truncated: size limit or connection lost"),80); else if(b->g.full)strlcpy_(b->msg,TR("Seite zu lang, Ende nicht dargestellt","Page too long, end not shown"),80); else if(r.status>=400)ksnprintf(b->msg,80,TR("Server meldet Fehler %d","Server reported error %d"),r.status); if(!post&&r.status<400){ lload(); ldel(hsl,&hsn,b->url); ladd(hsl,&hsn,b->url,b->g.title); lsave(HIF,hsl,hsn); } }
/* ---------- Bilder: nach dem Text, eines pro Durchlauf, damit Tasten wirken ---------- */
static char*ibuf; static u8*iout;
static void w_frame(win_t*w){ web_t*b=w->st; hpage*g=&b->g; if(b->inext>=g->nim||b->ifail>=3||b->state==ST_ERR)return; if(g->noimg)return; if(!ibuf){ ibuf=kmalloc(IMAX+1); iout=kmalloc(IOUT); if(!ibuf||!iout){ kfree(ibuf); kfree(iout); ibuf=0; iout=0; b->ifail=3; return; } } himg*m=&g->im[b->inext++]; if(m->state!=IM_WAIT)return; static char u[UL]; static http_res r; m->state=IM_FAIL; if(html_resolve(b->url,g->pool+m->src,u,UL))return; if(b->state==ST_SAFE&&strncmp(u,"https://",8))return; ksnprintf(w->foot,64,TR(" Lade Bild %d von %d ... "," Loading image %d of %d ... "),b->inext,g->nim); ui_render(); ui_show(); net_bg=1; int n=http_fetch(u,0,ibuf,IMAX,&r,0,HTTP_NOCOOKIE|HTTP_NOGZIP); net_bg=0; if(net_aborted){ b->ifail=3; return; } if(n<=0||r.status!=200||r.truncated){ b->ifail++; return; } b->ifail=0; long k=prog_decode(0,(u8*)ibuf,n,iout,IOUT,cw(w)-2,ch(w)-3,ui_rgb(C_PANEL),3000,0); if(k<4)return; int c_=iout[0]|iout[1]<<8,r_=iout[2]|iout[3]<<8; if(c_<1||c_>240||r_<1||r_>100||k!=4+(long)c_*r_*32)return; if(b->ibytes+k>16000000u)return; m->px=kmalloc(k-4); if(!m->px)return; memcpy(m->px,iout+4,k-4); b->ibytes+=k; m->cols=c_; m->rows=r_; m->id=gfx_newid(); m->state=IM_OK; int ln=m->line,on=g->nl; layout(b,b->wid); if(ln<b->top)b->top+=g->nl-on; }
/* ---------- Suche ---------- */
static int fold(u8 c){ if(c>='A'&&c<='Z')return c+32; if(c==0x8E)return 0x84; if(c==0x99)return 0x94; if(c==0x9A)return 0x81; return c; }
static int fmatch(const u8*p,int n,const char*f){ int i=0; for(;f[i];i++){ if(i>=n||fold(p[i])!=fold((u8)f[i]))return 0; } return 1; }
static int fline(hpage*g,int i,const char*f){ hline*l=&g->l[i]; int fl=strlen(f); for(int x=0;x+fl<=l->len;x++) if(fmatch(g->ch+l->off+x,l->len-x,f))return 1; return 0; }
static void fgo(web_t*b,int dir,int h){ hpage*g=&b->g; int s=b->fline; if(!b->find[0]||!g->nl)return; b->fhits=0; for(int i=0;i<g->nl;i++)b->fhits+=fline(g,i,b->find); if(!b->fhits){ strlcpy_(b->msg,TR("Nicht gefunden","Not found"),80); b->fline=-1; return; } int i=s; for(int k=0;k<g->nl;k++){ i+=dir; if(i>=g->nl)i=0; if(i<0)i=g->nl-1; if(fline(g,i,b->find))break; } b->fline=i; b->top=i>2?i-2:0; if(b->top+h>g->nl)b->top=g->nl-h; if(b->top<0)b->top=0; int idx=0; for(int k=0;k<=i;k++)idx+=fline(g,k,b->find); ksnprintf(b->msg,80,TR("Zeile %d von %d mit Treffer. Strg+G weiter, Esc beendet","Hit line %d of %d. Ctrl+G next, Esc ends search"),idx,b->fhits); }
static void w_draw(win_t*w){ web_t*b=w->st; if(b->wid!=cw(w))relay(b,cw(w)); int H_=ch(w)-2,W_=cw(w); hpage*g=&b->g; u8 bg=C_PANEL; cfill(w,AT(bg,C_LAV));
  static const u8 sa[]={AT(C_PANEL,C_LAV),AT(C_PANEL,C_NEON),AT(C_PANEL,C_GLOW),AT(C_PANEL,C_HOT),AT(C_PANEL,C_MID),AT(C_PANEL,C_VIOLET),AT(C_VOID,C_GLOW)};
  for(int x=0;x<W_;x++){ cput(w,x,0,' ',AT(C_RAISE,C_LAV)); cput(w,x,ch(w)-1,' ',AT(C_RAISE,C_LAV)); }
  const char*lab=b->state==ST_SAFE?TR(" Sicher "," Secure "):b->state==ST_PLAIN?TR(" UNVERSCHLÜSSELT "," NOT ENCRYPTED "):b->state==ST_ERR?TR(" Fehler "," Error "):" Violyx "; u8 la=b->state==ST_SAFE?AT(C_SEL,C_GLOW):b->state==ST_NEW?AT(C_RAISE,C_NEON):AT(C_HOT,C_VOID); ctext(w,0,0,la,lab); int lx=0; for(const char*p=lab;*p;p++) if((*p&0xC0)!=0x80)lx++; lx++; char u[100]; strlcpy_(u,b->url,W_-lx>98?99:W_-lx+1); int k=0; for(;u[k]&&lx+k<W_;k++)cput(w,lx+k,0,(u8)u[k],AT(C_RAISE,C_LAV));
  static u8 hl[420]; int fl_=b->find[0]?strlen(b->find):0; for(int y=0;y<H_;y++){ int i=b->top+y; if(i>=g->nl)break; hline*l=&g->l[i]; int fi=0; u16 fl=0; if(fl_){ memset(hl,0,420); for(int x=0;x<l->len&&x<W_;x++) if(x+fl_<=l->len&&fmatch(g->ch+l->off+x,l->len-x,b->find))for(int q=0;q<fl_&&x+q<420;q++)hl[x+q]=1; } for(int x=0;x<l->len&&x<W_;x++){ u32 o=l->off+x; u16 lk=g->lk[o]; u8 a=(b->sel>=0&&lk==b->sel+1)?AT(C_SEL,C_GLOW):sa[g->st[o]]; u8 c=g->ch[o]; if(lk&&c=='_'&&g->st[o]==HS_FIELD&&g->links[lk-1].field>=0){ if(fl!=lk){ fl=lk; fi=0; } int f=g->links[lk-1].field; const char*v=f<MAXF&&b->edit[f]?b->val[f]:g->pool+g->fld[f].value; int n=strlen(v); int c2=g->fld[f].cols,s0=n>c2?n-c2:0; c=fi<n-s0?(u8)v[s0+fi]:(u8)' '; fi++; } if(fl_&&hl[x<420?x:419])cput(w,x,y+1,c,AT(C_HOT,C_VOID)); else if(g->fg[o]&&a==sa[g->st[o]]&&g->st[o]!=HS_LINK)cput8(w,x,y+1,c,g->fg[o],C_PANEL); else cput(w,x,y+1,c,a); } }
  for(int i=0;i<g->nim;i++){ himg*m=&g->im[i]; if(m->state!=IM_OK||!m->px)continue; if(g->noimg)break; for(int r=0;r<m->rows;r++){ int y=m->line+r-b->top; if(y<0||y>=H_)continue; for(int x=0;x<m->cols&&m->x+x<W_;x++)cputg(w,m->x+x,y+1,m->id,m->px,m->cols*4,x,r); } }
  { tabs_t*T=b->T; if(T->n>1){ int x=W_-T->n*4-1; for(int i=0;i<T->n;i++,x+=4){ char t[5]; ksnprintf(t,5,i==T->cur?"[%d] ":" %d  ",i+1); ctext(w,x,0,i==T->cur?AT(C_SEL,C_GLOW):AT(C_RAISE,C_LAV),t); } } }
  char f[130]; f[0]=0; if(b->msg[0])strlcpy_(f,b->msg,130); else if(b->num)ksnprintf(f,130,TR("Link %d, Enter öffnet","Link %d, Enter opens"),b->num); else if(b->sel>=0&&b->sel<g->nlk){ int fd=g->links[b->sel].field; if(fd>=0)strlcpy_(f,g->fld[fd].type==HF_TEXT?TR("Eingabefeld: Enter zum Ausfüllen","Input field: press Enter to fill in"):TR("Knopf: Enter sendet das Formular","Button: press Enter to submit"),130); else strlcpy_(f,g->pool+g->links[b->sel].off,130); } else strlcpy_(f,TR("Strg+L Adresse  Strg+F Suchen  Strg+D Merken  Strg+B Liste  Strg+I Bilder","Ctrl+L Address  Ctrl+F Find  Ctrl+D Bookmark  Ctrl+B List  Ctrl+I Images"),130); if((int)strlen(f)>W_)f[W_]=0; ctext(w,0,ch(w)-1,AT(C_RAISE,C_LAV),f);
  int pct=g->nl>H_?(b->top*100)/(g->nl-H_>0?g->nl-H_:1):100; if(pct>100)pct=100; ksnprintf(w->foot,64," %d / %d (%d%%) ",b->top+1,g->nl,pct); win_title(w,g->title[0]?g->title:"Violyx Internet"); }
static int enc(char*o,int p,int max,const char*v,int cp){ for(;*v;v++){ u8 c=*v; u8 t[4]; int n=1; t[0]=c; if(cp&&c>=0x80){ u16 u=html_cp437_uni(c); if(u<0x800){ t[0]=0xC0|u>>6; t[1]=0x80|(u&63); n=2; } else { t[0]=0xE0|u>>12; t[1]=0x80|((u>>6)&63); t[2]=0x80|(u&63); n=3; } } for(int i=0;i<n;i++){ c=t[i]; if(p+4>=max)return -1; if((c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.'||c=='~')o[p++]=c; else if(c==' ')o[p++]='+'; else { o[p++]='%'; o[p++]="0123456789ABCDEF"[c>>4]; o[p++]="0123456789ABCDEF"[c&15]; } } } o[p]=0; return p; }
static void submit(win_t*w,web_t*b,int form,int btn){ hpage*g=&b->g; static char q[1300],url[UL],ful[UL]; int p=0; for(int i=0;i<g->nf;i++){ hfield*f=&g->fld[i]; if(f->form!=form)continue; if(f->type==HF_SUBMIT&&i!=btn)continue; const char*nm=g->pool+f->name; if(!*nm)continue; int ed=i<MAXF&&b->edit[i]; if(p){ if(p+2>=1300)goto big; q[p++]='&'; } p=enc(q,p,1300,nm,0); if(p<0||p+2>=1300)goto big; q[p++]='='; q[p]=0; p=enc(q,p,1300,ed?b->val[i]:g->pool+f->value,ed); if(p<0)goto big; }
  if(html_resolve(b->url[0]?b->url:"https://violyx.invalid/",g->pool+g->frm[form].action,url,UL)){ strlcpy_(b->msg,TR("Formularziel nicht unterstützt","Form target not supported"),80); return; } { char*h=strchr(url,'#'); if(h)*h=0; }
  if(g->frm[form].post){ load(w,b,url,1,0,q); return; } { char*h=strchr(url,'?'); if(h)*h=0; } if(ksnprintf(ful,UL,"%s?%s",url,q)>=UL)goto big; load(w,b,ful,1,0,0); return;
  big: strlcpy_(b->msg,TR("Formular zu groß","Form too large"),80); }
static void openlink(win_t*w,web_t*b,int id){ hpage*g=&b->g; static char in[UL]; int f=g->links[id].field; if(f>=0){ hfield*fd=&g->fld[f]; if(fd->type==HF_SUBMIT){ submit(w,b,fd->form,f); return; } if(f>=MAXF)return; static char v[VL]; strlcpy_(v,b->edit[f]?b->val[f]:g->pool+fd->value,VL); if(dlg_input(TR("Eingabe","Input"),TR("Text eingeben:","Enter text:"),v,VL)){ strlcpy_(b->val[f],v,VL); b->edit[f]=1; int tx=0; for(int i=0;i<g->nf;i++) if(g->fld[i].form==fd->form&&g->fld[i].type==HF_TEXT)tx++; if(tx==1)submit(w,b,fd->form,-1); } else if(!v[0]){ b->val[f][0]=0; b->edit[f]=1; } return; }
  const char*r=g->pool+g->links[id].off; if(r[0]=='#'){ jump(b,r+1,0); b->sel=-1; return; } if(b->internal&&!strncmp(r,"violyx:",7)){ strlcpy_(in,r,UL); load(w,b,in,1,0,0); return; } if(html_resolve(b->url[0]?b->url:"https://violyx.invalid/",r,in,UL)){ strlcpy_(b->msg,TR("Dieser Linktyp wird nicht unterstützt","This link type is not supported"),80); return; } load(w,b,in,1,0,0); }
static void newtab(win_t*w,const char*url);
static void clamp(web_t*b,int h){ int m=b->g.nl-h; if(b->top>m)b->top=m; if(b->top<0)b->top=0; }
static void w_key(win_t*w,key_t k){ web_t*b=w->st; hpage*g=&b->g; int h=ch(w)-2; static char in[UL];
  if(k.mods&M_CTRL){ tabs_t*T=b->T; if(k.key=='t'){ newtab(w,0); return; } if(k.key==K_PGDN||k.key==K_PGUP){ if(T->n>1){ T->cur=(T->cur+(k.key==K_PGDN?1:T->n-1))%T->n; w->st=T->t[T->cur]; } return; } if(k.key==K_ENTER){ if(b->sel>=0&&b->sel<g->nlk&&g->links[b->sel].field<0){ const char*r=g->pool+g->links[b->sel].off; if(r[0]=='#'||html_resolve(b->url[0]?b->url:"https://violyx.invalid/",r,in,UL))return; newtab(w,in); } return; } if(k.key=='f'){ static char f[64]; strlcpy_(f,b->find,64); dlg_fresh=1; if(dlg_input(TR("Auf der Seite suchen","Find on page"),TR("Suchtext:","Search for:"),f,64)){ strlcpy_(b->find,f,64); b->fline=b->top-1; b->msg[0]=0; fgo(b,1,h); } return; } if(k.key=='g'){ if(!b->find[0])strlcpy_(b->msg,TR("Erst mit Strg+F suchen","Search with Ctrl+F first"),80); else fgo(b,k.mods&M_SHIFT?-1:1,h); return; } if(k.key=='i'){ if(b->internal||!b->url[0])return; lload(); char ho[120]; hostof(b->url,ho,120); if(g->noimg){ ldel(noi,&non,ho); g->noimg=0; b->inext=0; b->ifail=0; strlcpy_(b->msg,TR("Bilder an für diese Website","Images on for this site"),80); } else { ladd(noi,&non,ho,""); g->noimg=1; strlcpy_(b->msg,TR("Bilder aus für diese Website","Images off for this site"),80); } lsave(NOF,noi,non); relay(b,b->wid); return; } if(k.key=='b'){ load(w,b,"violyx:bookmarks",1,0,0); return; } if(k.key=='h'){ load(w,b,"violyx:history",1,0,0); return; } if(k.key=='d'){ if(!b->url[0]||b->internal||b->state==ST_ERR){ strlcpy_(b->msg,TR("Diese Seite lässt sich nicht merken","This page cannot be bookmarked"),80); return; } lload(); if(ldel(bmk,&bml,b->url))strlcpy_(b->msg,TR("Lesezeichen entfernt","Bookmark removed"),80); else { ladd(bmk,&bml,b->url,g->title); strlcpy_(b->msg,TR("Lesezeichen gespeichert","Bookmark saved"),80); } lsave(BMF,bmk,bml); return; } if(k.key=='l'){ strlcpy_(in,b->url,UL); dlg_fresh=1; if(dlg_input(TR("Adresse","Address"),TR("Adresse eingeben:","Enter address:"),in,600))load(w,b,in,1,0,0); return; } if(k.key=='s'){ char n[VFS_PATH],p[VFS_PATH]; const char*t=b->url; for(const char*q=b->url;*q&&*q!='?'&&*q!='#';q++) if(*q=='/'&&q[1]&&q[1]!='?')t=q+1; int l=0; ksnprintf(n,VFS_PATH,"%s/",fs_ok()?"/downloads":fsx_home()); l=strlen(n); while(*t&&*t!='?'&&*t!='#'&&*t!='/'&&l<60)n[l++]=*t++; n[l]=0; if(l<=11)strlcpy_(n,"/downloads/page.html",VFS_PATH); if(dlg_input(TR("Seite speichern","Save page"),TR("Pfad und Dateiname:","Path and file name:"),n,VFS_PATH-1)){ if(vfs_norm("/downloads",n,p,VFS_PATH))return; int r=fsx_write(p,b->html,b->hlen,fs_now()); strlcpy_(b->msg,r?vfs_errstr(r,cfg_lang):TR("Gespeichert","Saved"),80); } return; } if(k.key=='r'){ if(b->url[0]){ strlcpy_(in,b->url,UL); load(w,b,in,0,b->top,0); } return; } if(k.key==K_HOME)b->top=0; else if(k.key==K_END)b->top=g->nl; clamp(b,h); return; }
  switch(k.key){ case K_UP:b->top--;break; case K_DOWN:b->top++;break; case K_PGUP:b->top-=h-1;break; case K_PGDN:case ' ':b->top+=h-1;break; case K_HOME:b->top=0;break; case K_END:b->top=g->nl;break;
   case K_TAB:{ int vis=b->sel>=0&&g->links[b->sel].line>=b->top&&g->links[b->sel].line<b->top+h; int back=k.mods&M_SHIFT,i; if(back){ i=vis?b->sel-1:g->nlk-1; if(!vis)while(i>=0&&g->links[i].line>=b->top+h)i--; while(i>=0&&g->links[i].line<0)i--; if(i<0){ i=g->nlk-1; while(i>=0&&g->links[i].line<0)i--; } } else { i=vis?b->sel+1:0; if(!vis)while(i<g->nlk&&g->links[i].line<b->top)i++; while(i<g->nlk&&g->links[i].line<0)i++; if(i>=g->nlk){ i=0; while(i<g->nlk&&g->links[i].line<0)i++; if(i>=g->nlk)i=-1; } } if(i>=0){ b->sel=i; int l=g->links[i].line; if(l<b->top)b->top=l; if(l>=b->top+h)b->top=l-h/2; } b->msg[0]=0; break; }
   case K_ENTER: b->msg[0]=0; if(b->num){ int n=b->num-1; b->num=0; if(n<g->nlk&&n>=0){ b->sel=n; openlink(w,b,n); } else strlcpy_(b->msg,TR("Diese Nummer gibt es nicht","No such number"),80); return; } if(b->sel>=0&&b->sel<g->nlk){ openlink(w,b,b->sel); return; } break;
   case K_BS: if(b->nh){ b->nh--; strlcpy_(in,b->hist[b->nh],UL); load(w,b,in,0,b->htop[b->nh],0); return; } else strlcpy_(b->msg,TR("Keine vorherige Seite","No previous page"),80); break;
   case 'n': case 'N': g->nums=!g->nums; b->num=0; b->wid=0; return;
   default: if(k.key>='0'&&k.key<='9'&&g->nums){ if(b->num<10000)b->num=b->num*10+k.key-'0'; } return; }
  clamp(b,h); }
static void web_kill(web_t*b){ hpage*g=&b->g; if(g->im)img_reset(b); kfree(g->l);kfree(g->ch);kfree(g->st);kfree(g->fg);kfree(g->lk);kfree(g->pool);kfree(g->links);kfree(g->anch);kfree(g->fld);kfree(g->frm);kfree(g->im);kfree(b->val);kfree(b->edit);kfree(b->html);kfree(b->hist);kfree(b); }
static web_t*web_new(void){ web_t*b=kmalloc(sizeof*b); if(!b)return 0; memset(b,0,sizeof*b); hpage*g=&b->g; g->maxl=120000;g->cap=2000000;g->pc=1024*1024;g->maxlk=20000;g->maxan=8192; g->l=kmalloc(sizeof(hline)*g->maxl);g->ch=kmalloc(g->cap);g->st=kmalloc(g->cap);g->fg=kmalloc(g->cap);g->lk=kmalloc(g->cap*2);g->pool=kmalloc(g->pc);g->links=kmalloc(sizeof(hlink)*g->maxlk);g->anch=kmalloc(sizeof(hanchor)*g->maxan);g->maxf=MAXF;g->maxfrm=64;g->fld=kmalloc(sizeof(hfield)*g->maxf);g->frm=kmalloc(sizeof(hform)*g->maxfrm);g->im=kmalloc(sizeof(himg)*MAXIM);b->val=kmalloc(MAXF*VL);b->edit=kmalloc(MAXF);b->html=kmalloc(HMAX+1);b->hist=kmalloc(NH*UL); if(!g->fld||!g->frm||!g->im||!b->val||!b->edit||!g->l||!g->ch||!g->st||!g->fg||!g->lk||!g->pool||!g->links||!g->anch||!b->html||!b->hist){ if(g->im)memset(g->im,0,sizeof(himg)*MAXIM); web_kill(b); return 0; } memset(g->im,0,sizeof(himg)*MAXIM); g->maxim=MAXIM; memset(b->edit,0,MAXF); b->fline=-1; return b; }
static void startpage(web_t*b,int wd){ if(cfg_lang)setpage(b,START_EN,sizeof START_EN-1,wd); else setpage(b,START,sizeof START-1,wd); }
static void newtab(win_t*w,const char*url){ web_t*a=w->st; tabs_t*T=a->T; if(T->n>=MAXT){ strlcpy_(a->msg,TR("Mehr Tabs gehen nicht","No more tabs possible"),80); return; } web_t*b=web_new(); if(!b){ strlcpy_(a->msg,TR("Nicht genug Arbeitsspeicher für einen Tab","Not enough memory for a tab"),80); return; } b->T=T; T->t[T->n]=b; T->cur=T->n++; w->st=b; startpage(b,cw(w)); if(url){ static char u[UL]; strlcpy_(u,url,UL); load(w,b,u,0,0,0); } else { static char in[UL]; in[0]=0; dlg_fresh=1; if(dlg_input(TR("Neuer Tab","New tab"),TR("Adresse eingeben:","Enter address:"),in,600))load(w,b,in,0,0,0); } }
/* Esc beendet erst die Suche, dann den Tab, zuletzt das Fenster */
static int w_close(win_t*w){ if(ui_quitting)return 1; web_t*b=w->st; tabs_t*T=b->T; if(b->find[0]){ b->find[0]=0; b->msg[0]=0; return 0; } if(T->n<2)return 1; int c=T->cur; web_kill(b); for(int i=c;i<T->n-1;i++)T->t[i]=T->t[i+1]; T->n--; if(T->cur>=T->n)T->cur=T->n-1; w->st=T->t[T->cur]; return 0; }
static void w_free(win_t*w){ web_t*b=w->st; tabs_t*T=b->T; cookie_save(); for(int i=0;i<T->n;i++)web_kill(T->t[i]); kfree(T); }
static const app_t web_app={w_draw,w_key,0,w_close,w_free,w_frame};
void app_web(void){ web_app_open(0); }
void web_app_open(const char*url){ tabs_t*T=kmalloc(sizeof*T); web_t*b=T?web_new():0; if(!b){ kfree(T); dlg_msg("Internet",TR("Nicht genug Arbeitsspeicher.","Not enough memory.")); return; } memset(T,0,sizeof*T); T->t[0]=b; T->n=1; b->T=T; win_t*w=win_open("Violyx Internet",1,1,78,23,&web_app,b); if(!w){ web_kill(b); kfree(T); return; } win_zoom(w); startpage(b,cw(w)); if(url)load(w,b,url,0,0,0); }
